function slackSignatureInput(headers, raw, nowSeconds) {
  const timestamp = headers?.["x-slack-request-timestamp"];
  const signature = headers?.["x-slack-signature"];
  if (
    typeof timestamp !== "string" ||
    !/^\d{10}$/.test(timestamp) ||
    Math.abs(nowSeconds - Number(timestamp)) > 300 ||
    typeof signature !== "string" ||
    !/^v0=[a-f0-9]{64}$/.test(signature) ||
    typeof raw !== "string" ||
    !/^[\x20-\x7e]{1,16384}$/.test(raw) ||
    !/^application\/x-www-form-urlencoded(?:\s*;|$)/i.test(headers?.["content-type"] ?? "")
  ) {
    return { ready: false, base: "v0:invalid", signature: "" };
  }
  return {
    ready: true,
    base: "v0:" + timestamp + ":" + raw,
    signature,
    raw,
    retry: /^\d+$/.test(headers["x-slack-retry-num"] ?? ""),
  };
}

let raw = "";
try {
  const bytes = await helpers.getBinaryDataBuffer(0, "data");
  if (bytes.length <= 16384 && !bytes.some((byte) => byte < 32 || byte > 126))
    raw = Buffer.from(bytes).toString("ascii");
} catch {}
return { json: slackSignatureInput($json.headers, raw, Math.floor(Date.now() / 1000)) };

function equalSignature(received, digest) {
  if (
    typeof digest !== "string" ||
    !/^[a-f0-9]{64}$/.test(digest) ||
    typeof received !== "string" ||
    received.length !== 67
  )
    return false;
  const expected = "v0=" + digest;
  let difference = 0;
  for (let i = 0; i < expected.length; i++)
    difference |= received.charCodeAt(i) ^ expected.charCodeAt(i);
  return difference === 0;
}

function parseSlackForm(raw) {
  const decoded = Object.create(null);
  const unescape = (value) => decodeURIComponent(value.replaceAll("+", " "));
  for (const pair of raw.split("&")) {
    const separator = pair.indexOf("=");
    if (separator < 0) throw new Error("Malformed Slack command.");
    const key = unescape(pair.slice(0, separator));
    if (!key || Object.hasOwn(decoded, key)) throw new Error("Repeated Slack command field.");
    decoded[key] = unescape(pair.slice(separator + 1));
  }
  return decoded;
}

function privateReply(text) {
  return { response_type: "ephemeral", text };
}

function admittedIncident(prepared, digest, settings) {
  if (!prepared.ready || !equalSignature(prepared.signature, digest)) {
    return { query: false, status: 401, reply: { error: "Invalid Slack signature." } };
  }
  let form;
  try {
    form = parseSlackForm(prepared.raw);
  } catch {
    return { query: false, status: 400, reply: { error: "Invalid Slack command." } };
  }
  const {
    team_id: team,
    channel_id: channel,
    user_id: user,
    command,
    response_url: responseUrl,
  } = form;
  if (
    !/^T[A-Z0-9]{3,}$/.test(settings.teamId) ||
    team !== settings.teamId ||
    !settings.channelIds.includes(channel) ||
    !/^[CG][A-Z0-9]{3,}$/.test(channel ?? "") ||
    !settings.userIds.includes(user) ||
    !/^[UW][A-Z0-9]{3,}$/.test(user ?? "") ||
    command !== settings.command
  ) {
    return {
      query: false,
      status: 200,
      reply: privateReply("This command is unavailable in this channel or for this user."),
    };
  }
  const responsePath =
    /^https:\/\/hooks\.slack\.com\/commands\/(T[A-Z0-9]+)\/[A-Za-z0-9_-]+\/[A-Za-z0-9_-]+$/;
  const shortPath = /^https:\/\/hooks\.slack\.com\/commands\/[0-9]+\/[A-Za-z0-9_-]+$/;
  const trustedReply =
    typeof responseUrl === "string" &&
    responseUrl.length <= 768 &&
    (responseUrl.match(responsePath)?.[1] === team || shortPath.test(responseUrl));
  if (!trustedReply) {
    return { query: false, status: 400, reply: { error: "Invalid Slack response destination." } };
  }
  if (prepared.retry)
    return {
      query: false,
      status: 200,
      reply: privateReply("This command has already been received."),
    };
  const incident = form.text?.trim().toUpperCase();
  if (!/^INC[0-9]{1,15}$/.test(incident ?? "")) {
    return {
      query: false,
      status: 200,
      reply: privateReply("Enter one incident number, for example INC0012345."),
    };
  }
  if (
    typeof settings.instance !== "string" ||
    !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(settings.instance)
  ) {
    return {
      query: false,
      status: 200,
      reply: privateReply("The ServiceNow lookup is unavailable."),
    };
  }
  return {
    query: true,
    incident,
    responseUrl,
    origin: "https://" + settings.instance + ".service-now.com",
  };
}

const settings = {
  command: "/incident",
  teamId: "",
  channelIds: [],
  userIds: [],
  instance: "",
};
return {
  json: admittedIncident($("Read the signed request bytes").first().json, $json.digest, settings),
};

function privateReply(text) {
  return { response_type: "ephemeral", text };
}

function incidentReply(request, status, body) {
  const problem = () =>
    privateReply(
      "Could not look up this incident in ServiceNow. Try again or contact your administrator.",
    );
  if (status !== 200 || !Array.isArray(body?.result)) return problem();
  if (body.result.length === 0)
    return privateReply("No incident was found with that number. Check the number and try again.");
  if (body.result.length !== 1) return problem();
  const record = body.result[0];
  const value = (key) => {
    const field = record?.[key];
    return field && typeof field === "object" ? field.value : field;
  };
  const display = (key) => {
    const field = record?.[key];
    const text = field && typeof field === "object" ? field.display_value : field;
    return typeof text === "string" && text.trim()
      ? [...text].slice(0, 1800).join("")
      : "Unavailable";
  };
  const sysId = value("sys_id");
  if (
    value("number") !== request.incident ||
    typeof sysId !== "string" ||
    !/^[a-f0-9]{32}$/i.test(sysId)
  )
    return problem();
  const fields = [
    ["Incident ID", "number"],
    ["Description", "short_description"],
    ["Severity", "severity"],
    ["Caller", "caller_id"],
    ["Priority", "priority"],
    ["State", "incident_state"],
    ["Category", "category"],
    ["Date opened", "opened_at"],
  ].map(([label, key]) => ({
    type: "plain_text",
    text: label + ":\n" + display(key),
    emoji: false,
  }));
  const url =
    request.origin + "/nav_to.do?uri=" + encodeURIComponent("incident.do?sys_id=" + sysId);
  return {
    response_type: "in_channel",
    text: "ServiceNow incident " + request.incident,
    blocks: [
      { type: "header", text: { type: "plain_text", text: "ServiceNow Incident Notification" } },
      { type: "section", fields },
      {
        type: "actions",
        elements: [
          {
            type: "button",
            text: { type: "plain_text", text: "View Incident" },
            url,
            action_id: "view_incident",
          },
        ],
      },
    ],
  };
}

const request = $("Verify Slack and approve the incident lookup").first().json;
return { json: { payload: incidentReply(request, $json.statusCode, $json.body) } };

if ($json.statusCode !== 200)
  throw new Error(
    "Slack did not confirm the deferred reply. Review the channel before attempting another command.",
  );
return { json: { delivery: "accepted" } };
